from pathlib import Path
import json,html
from build import OUT,ROOT
m=json.loads((OUT/'manifest.json').read_text());names={'1':'White Editorial','2':'Yellow Headline','3':'Two-Position Montage','4':'Dark With Red Accent'}
parts=['''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hamstring Curls: Four Real Screenshot Covers</title><style>*{box-sizing:border-box}body{margin:0;background:#111923;color:#f1f4f7;font:17px/1.5 -apple-system,BlinkMacSystemFont,Arial,sans-serif}main{max-width:1400px;margin:auto;padding:28px 20px}h1{font-size:35px;line-height:1.15}p{max-width:900px;color:#cbd4df}.notice{border:1px solid #476176;background:#1c2b3b;padding:18px 22px;border-radius:12px}.nav{display:flex;gap:14px;flex-wrap:wrap;margin:24px 0}.nav a{padding:9px 20px;background:#243344;border-radius:7px}a{color:#63e0ed;text-decoration:none}.sheet{width:100%;height:auto}.pair{display:grid;grid-template-columns:1fr 1fr .75fr;gap:20px}.pair img{width:100%;height:auto}section{margin:28px 0;padding:22px;background:#192534;border:1px solid #344658;border-radius:12px}figure{margin:0}figcaption{margin-bottom:10px;color:#c7d2df}summary{cursor:pointer;color:#63e0ed;font-weight:700}.comparison{width:100%;height:auto;margin-top:16px}@media(max-width:700px){main{padding:20px 12px}.pair{grid-template-columns:1fr 1fr;gap:10px}.grid{max-width:250px;grid-column:1/3}section{padding:14px}h1{font-size:28px}}</style></head><body><main><h1>How To Do Hamstring Curls</h1><div class="notice"><strong>Four New Designs From Your Real Exercise Screenshots</strong><p>These replace the previous five concepts. The photographs come from your actual hamstring-curl footage, with photographic touch-ups. Design 3 shows both the extended and curled positions.</p><p>Choose <strong>1, 2, 3 or 4</strong> in this chat. Every design has a separate Instagram and YouTube Shorts layout. Your approved Gemini R3 film is unchanged. No new cover is installed or scheduled.</p></div><div class="nav">''']
for k in '1234':parts.append(f'<a href="#design-{k}">Design {k}</a>')
parts.append('<a href="#sources">Original Screenshots</a></div><a href="four-cover-choices.jpg"><img class="sheet" src="four-cover-choices.jpg" alt="Four designs in Instagram and YouTube layouts"></a>')
for k in '1234':
 parts.append(f'<section id="design-{k}"><h2>{k}. {names[k]}</h2><div class="pair">')
 for platform in ['instagram','youtube']:
  row=next(x for x in m['outputs'] if x['design']==k and x['platform']==platform);rel=Path(row['path']).relative_to(OUT.relative_to(ROOT)).as_posix()
  parts.append(f'<figure><figcaption>{platform.title()}{" Shorts" if platform=="youtube" else ""}</figcaption><a href="{rel}"><img src="{rel}" alt="Design {k}, {platform}"></a></figure>')
 parts.append(f'<figure class="grid"><figcaption>Instagram Profile Crop</figcaption><img src="grid/{k}.jpg" alt="Design {k}, actual profile crop"></figure></div></section>')
parts.append('''<section id="sources"><h2>Original Screenshots And Touch-Ups</h2><p>The original video screenshots are shown next to the touched-up photographs. Open either version to inspect the full size.</p><a href="source-comparison.jpg"><img class="comparison" src="source-comparison.jpg" alt="Original and touched-up real screenshots"></a><div class="nav"><a href="sources/curled-original.png">Curled: Original</a><a href="sources/curled-retouched.png">Curled: Touched Up</a><a href="sources/extended-original.png">Extended: Original</a><a href="sources/extended-retouched.png">Extended: Touched Up</a></div></section><p>After your pick: prepare the approved covers and platform media, verify uploads, then queue the film or place it on the shared waiting list.</p></main></body></html>''')
(OUT/'index.html').write_text(''.join(parts));print(OUT/'index.html')
